/** 扁平 [x,y,x,y,…] → [[x,y],…]，只在建图时展开一次 */
export const COAST = RINGS.map((group) => group.map((flat) => {
  const pts = [];
  for (let i = 0; i < flat.length; i += 2) pts.push([flat[i], flat[i + 1]]);
  return pts;
}));
